export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog'
  }
};

export default function HomePage({ 
  searchParams 
}: { 
  searchParams: { 
    posts: Array<{ 
      id: number; 
      title: string; 
      body: string; 
    }>; 
    userAgent: string; 
    timestamp: string; 
  } 
}) {
  const posts = searchParams.posts || [];
  const userAgent = searchParams.userAgent || '';
  const timestamp = searchParams.timestamp || '';

  const navigateToBlog = () => {
    window.location.href = '/blog';
  };

  return (
    <>
      <div>
        <h1>Welcome to My Blog</h1>
        <p>Server-side rendered at: {timestamp}</p>
        <p>Your user agent: {userAgent}</p>

        <h2>Recent Posts</h2>
        <ul>
          {posts.map(post => (
            <li key={post.id}>
              <a href={`/blog/${post.id}`}>{post.title}</a>
            </li>
          ))}
        </ul>

        <button onClick={navigateToBlog}>
          View All Posts
        </button>
      </div>
    </>
  );
}

