import { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog'
  }
};

async function fetchPosts() {
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5')
    .then(res => res.json());

  return posts;
}

export default async function HomePage() {
  const posts = await fetchPosts();
  const userAgent = ''; // This would come from headers in a real app
  const timestamp = new Date().toISOString();

  return (
    <>
      <div>
        <h1>Welcome to My Blog</h1>
        <p>Server-side rendered at: {timestamp}</p>
        <p>Your user agent: {userAgent}</p>

        <h2>Recent Posts</h2>
        <ul>
          {posts.map(post => (
            <li key={post.id}>
              <a href={`/blog/${post.id}`}>{post.title}</a>
            </li>
          ))}
        </ul>

        <a href="/blog">
          View All Posts
        </a>
      </div>
    </>
  );
}

